use erp;



select id,sc_sm_id,batch_id from acc_bill_generate_process
 where date(created_on) >= '2026-02-01' and status = 'IN-PROGRESS';


SELECT 
    a.sc_sm_id,
    a.batch_id,
    DATE(a.created_on) 'Date',
    COALESCE(a.updated_on),
    COUNT(DISTINCT a.batch_id) 'Total Batches Created',
    COUNT(a.id) 'Total Bills Created',
    COALESCE(SUM(a.status = 'IN-QUEUE'), 0) 'Total_Process_IN_QUEUE',
    COALESCE(SUM(a.status = 'IN-PROGRESS'), 0) 'Total_Process_IN_PROCESS',
    COALESCE(SUM(a.status = 'COMPLETED'), 0) 'Total Process IN-COMPLETED',
    COALESCE(SUM(a.status = 'FAILED'
                AND a.error_data IS NOT NULL),
            0) 'Total Process FAILED',
    COALESCE(SUM(a.status = 'FAILED'
                AND a.error_data IS NULL),
            0) 'Total Process FAILED without Error',
    COALESCE(a.error_data)
FROM
    acc_bill_generate_process a
WHERE
    a.id > 70215690 and a.is_manual = '0'
GROUP BY DATE(a.created_on);


